/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, Watch } from '@stencil/core';
import { NEXT_BUTTON_LABEL, PREVIOUS_BUTTON_LABEL } from '../../a11y';

@Component({
  tag: 'groupui-simple-pagination',
  styleUrl: 'simple-pagination.scss',
  shadow: true,
})
export class SimplePagination {
  /**
   *  Number of overall pages
   */
  @Prop() readonly pageCount: number;

  /**
   * Number of displayed pages. Minimum is five. Values below five have no effect.
   */
  @Prop() readonly displayedPageCount: number = 5;

  /**
   * Selected page
   */
  @Prop({ mutable: true, reflect: true }) selectedPage: number = 1;

  /**
   *  Text for the previous button
   */
  @Prop() readonly previousButtonText: string;

  /**
   *  Text for the next button
   */
  @Prop() readonly nextButtonText: string;

  /**
   * aria-label for the previous button. The default value is 'Previous'.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-previous-button' }) readonly a11yLabelPreviousButton: string =
    PREVIOUS_BUTTON_LABEL;

  /**
   * aria-label for the next button. The default value is 'Next'.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-next-button' }) readonly a11yLabelNextButton: string =
    NEXT_BUTTON_LABEL;

  /**
   * dispatched on page select => 'event.detail' contains the selected page
   */
  @Event({ bubbles: false, composed: false }) groupuiPageChange: EventEmitter<number>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @Watch('selectedPage')
  onSelectedPageChanged() {
    this.groupuiPageChange.emit(this.selectedPage);
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (this.isAnySelectingKeyPressed(event) && this.isPageFocused()) {
      const focusedPage = this.host.shadowRoot.activeElement.getAttribute('data-page');
      this.selectedPage = parseInt(focusedPage);
      event.preventDefault();
    }
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private isPageFocused() {
    return this.host.shadowRoot.activeElement.hasAttribute('data-page');
  }

  private isAnySelectingKeyPressed(event: KeyboardEvent) {
    return event.code === 'Enter' || event.code === 'Space';
  }

  private selectPage = (page: number) => {
    this.selectedPage = page;
  };

  private getAriaLabel() {
    const paginationParentElement = this.host.closest('[aria-label="pagination"]');
    return paginationParentElement ? undefined : 'pagination';
  }

  private pageElements(): HTMLElement[] {
    const pages = Array.from({ length: this.pageCount }, (_, i) => i + 1);

    const sanitizedDisplayedPageCount = this.displayedPageCount >= 5 ? this.displayedPageCount : 5;

    let result: number[] = [];

    if (this.pageCount > sanitizedDisplayedPageCount) {
      const staticPages = this.staticPages(pages);
      result = staticPages;
      const missingPages = pages.filter((page) => !staticPages.includes(page));

      let displayedPagesLeftCount = sanitizedDisplayedPageCount - staticPages.length;

      if (displayedPagesLeftCount > 0) {
        if (this.selectedPage === undefined) {
          result = result.concat(missingPages.slice(0, displayedPagesLeftCount));
        } else {
          while (displayedPagesLeftCount > 0) {
            const nearestPage = this.findNearestPage(missingPages, this.selectedPage);
            result.push(nearestPage);
            displayedPagesLeftCount--;
            this.removePage(missingPages, nearestPage);
          }
        }
      }

      result = result.sort((a, b) => a - b);
    } else {
      result = pages;
    }

    return result.flatMap((page, index) => {
      const elements = [];
      if (this.isGap(index, page, result)) {
        elements.push(<div class="placeholder">...</div>);
      }
      elements.push(
        <button
          tabIndex={0}
          data-page={page}
          class={page === this.selectedPage ? 'page selected' : 'page'}
          aria-current={page === this.selectedPage ? 'page' : undefined}
          onClick={() => this.selectPage(page)}
        >
          <span>{page}</span>
        </button>
      );
      return elements;
    });
  }

  private isGap(index, page, pages) {
    return index > 0 && page - 1 !== pages[index - 1];
  }

  private staticPages(pages: number[]) {
    return pages.filter(
      (page) =>
        this.isFirstPage(page) ||
        this.isLastPage(page) ||
        this.isPreviousPage(page) ||
        this.isNextPage(page) ||
        this.isSelectedPage(page)
    );
  }

  private removePage(missingPages: number[], nearestPage) {
    const nearestPageIndex = missingPages.indexOf(nearestPage);
    missingPages.splice(nearestPageIndex, 1);
  }

  private findNearestPage(pages, page) {
    return pages.reduce((prev, curr) => (Math.abs(curr - page) <= Math.abs(prev - page) ? curr : prev));
  }

  private isFirstPage(pageNumber) {
    return pageNumber === 1;
  }

  private isLastPage(pageNumber) {
    return pageNumber === this.pageCount;
  }

  private isPreviousPage(pageNumber) {
    return this.isPreviousPageAvailable() && pageNumber === this.selectedPage - 1;
  }

  private isNextPage(pageNumber) {
    return this.isNextPageAvailable() && pageNumber === this.selectedPage + 1;
  }

  private isPreviousPageAvailable() {
    return this.selectedPage !== undefined && this.selectedPage > 1;
  }

  private isNextPageAvailable() {
    return this.selectedPage !== undefined && this.selectedPage < this.pageCount;
  }

  private isSelectedPage(pageNumber) {
    return pageNumber === this.selectedPage;
  }

  private selectPreviousPage = () => {
    this.selectedPage = Math.max(1, this.selectedPage - 1);
  };

  private selectNextPage = () => {
    this.selectedPage = Math.min(this.pageCount, this.selectedPage + 1);
  };

  private isPreviousButtonDisabled(): boolean {
    return this.selectedPage === 1;
  }

  private isNextButtonDisabled(): boolean {
    return this.selectedPage >= this.pageCount;
  }

  private isPreviousButtonIconOnly(): boolean {
    return this.previousButtonText === undefined;
  }

  private isNextButtonIconOnly(): boolean {
    return this.nextButtonText === undefined;
  }

  render() {
    return (
      <Host>
        <nav aria-label={this.getAriaLabel()}>
          <groupui-button
            id="pagination-button-previous"
            tabIndex={0}
            class="pagination__previous"
            iconLeft="chevron-left-16"
            variant="tertiary"
            size="s"
            aria-label={this.a11yLabelPreviousButton}
            icon-only={this.isPreviousButtonIconOnly()}
            onClick={this.selectPreviousPage}
            disabled={this.isPreviousButtonDisabled()}
          >
            {this.previousButtonText}
          </groupui-button>
          {this.pageElements()}
          <groupui-button
            id="pagination-button-next"
            tabIndex={0}
            class="pagination__next"
            icon-right="chevron-right-16"
            variant="tertiary"
            size="s"
            aria-label={this.a11yLabelNextButton}
            icon-only={this.isNextButtonIconOnly()}
            onClick={this.selectNextPage}
            disabled={this.isNextButtonDisabled()}
          >
            {this.nextButtonText}
          </groupui-button>
        </nav>
      </Host>
    );
  }
}
