/* eslint-disable no-undef */
import {
  Component,
  Element,
  Event,
  EventEmitter,
  forceUpdate,
  h,
  Host,
  Listen,
  Method,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { debounceTime, Subject, takeUntil } from 'rxjs';
import { CLEAR_BUTTON_LABEL } from '../../a11y';
import { FormDataEvent, FormSize, SelectedOption, SelectedOptionEvent, Severity } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

type SelectItem =
  | { type: 'option'; element: HTMLGroupuiSelectOptionElement }
  | { type: 'option-group'; element: HTMLGroupuiSelectOptionGroupElement };

type FocusOption = HTMLGroupuiSelectOptionElement | HTMLGroupuiSelectOptionGroupElement;

type FocusedOptionInSelect =
  | { index: number; type: 'option'; element: HTMLGroupuiSelectOptionElement }
  | { index: number; type: 'option-group'; element: HTMLGroupuiSelectOptionGroupElement };

/**
 * @nativeEvent click  - dispatched when select was clicked => 'event.target.value' delivers the value of the select
 * @nativeEvent change  - dispatched when option has changed => 'event.target.value' delivers the value of the select
 *
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-select',
  styleUrl: 'select.scss',
  shadow: { delegatesFocus: true },
})
export class Select {
  /**
   * severity of the select
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity = 'none';

  /**
   * placeholder of the select-field
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * set max-height for the options container (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly maxHeight: string = 'none';

  /**
   * selected value of select, can also be used to preselect an option at startup
   */
  @Prop({ reflect: true, mutable: true }) value: string;

  /**
   * name of the select element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * deactivates the select
   */
  @Prop({ reflect: true }) readonly disabled?: boolean;

  /**
   * toggles readonly mode
   */
  @Prop({ reflect: true }) readonly readonly: boolean;

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * specifies that an option must be selected before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * show status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * disable internal validation
   */
  @Prop({ reflect: true }) readonly noValidation: boolean = false;

  /**
   * shows a clear icon within the input field that clears the selection on click
   */
  @Prop({ reflect: true }) readonly showClearIcon: boolean;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * sets a custom accessible text for the clear button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-clear-button' }) readonly a11yLabelClearButton: string;

  /**
   * toggle built-in search behaviour
   */
  @Prop({ reflect: true }) readonly builtInSearch: boolean = false;

  /**
   * makes the built-in search case-insensitive
   */
  @Prop({ reflect: true }) readonly caseInsensitiveSearch: boolean = false;

  /**
   * makes the select searchable
   */
  @Prop({ reflect: true }) readonly searchable: boolean = false;

  /**
   * value of the search-field
   */
  @Prop({ reflect: true, mutable: true }) searchValue: string;

  /**
   * sets the size of the input field
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   *
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<void>;

  /**
   * is dispatched when the clear icon was clicked
   */
  @Event({ bubbles: false }) groupuiClearClicked: EventEmitter<void>;

  /**
   * is dispatched when a search is started (only when searchable is true) => 'event.detail' delivers the selectedOption and the searchString
   */
  @Event({ bubbles: false }) groupuiSearchStarted: EventEmitter<SelectedOptionEvent>;

  /**
   * is dispatched when a search is cleared (only when searchable is true)
   */
  @Event({ bubbles: false }) groupuiSearchCleared: EventEmitter<void>;

  /**
   * for react user only - works only when searchable. Is dispatched when the value is changed on key input
   */
  @Event({ bubbles: false }) groupuiInput: EventEmitter<void>;

  /**
   * works only when searchable. Is dispatched when the input is focused
   */
  @Event({ bubbles: false }) groupuiInputFocused: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() searchOngoing: boolean;
  @State() isEveryOptionFilteredOut: boolean;
  @State() expanded: boolean;

  private readonly KEYBOARD_FOCUS = 'keyboard-focus';
  private allOptions: SelectItem[] = [];
  private allBaseOptions: SelectItem[] = [];
  private focusableItems: FocusOption[] = [];
  private inputTyping = new Subject<string>();
  private destroy = new Subject<void>();

  @State() invalid: boolean;

  @State() hasFocus: boolean;
  @State() clearFocus: boolean;
  @State() tabbed: boolean;
  @State() keyboardFocus: FocusedOptionInSelect = undefined;
  private selectedIconObserver: MutationObserver;

  private ariaAttributes: AriaAttributes;

  private static CONSOLE_WARN_MESSAGE = 'Predefined value not found in any groupui-select-option';

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled || this.readonly) {
      event.stopPropagation();
    }
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (this.readonly || this.disabled) {
      return;
    }

    if (this.isSearchInputFocused()) {
      if (event.code === 'Space') {
        return;
      }
      if (event.code === 'Enter') {
        if (!this.keyboardFocus?.type) {
          this.emitSearchStartedEvent();
          return;
        }
      }
      if (event.code === 'Escape') {
        this.clearSearchField();
        return;
      }
    }

    if (event.code === 'Tab') {
      this.tabbed = true;
    }

    if (this.clearFocus) {
      if (event.code === 'Enter' || event.code === 'Space') {
        event.preventDefault();
        this.handleClearIconClick(event);
        if (this.searchable) {
          this.getSearchInputElement().focus();
        } else {
          this.focusDropdown();
        }
        return;
      }
    }

    if (this.expanded) {
      if (this.anySelectingKeyPressed(event)) {
        event.preventDefault();
        this.selectOption();
        if (this.searchable) {
          this.getSearchInputElement().focus();
        } else {
          this.focusDropdown();
        }
        return;
      }
      if (event.code === 'Tab') {
        this.selectOption();
        return;
      }
      if (event.code === 'ArrowDown') {
        event.preventDefault();
        this.focusOption('next');
        return;
      }
      if (event.code === 'ArrowUp') {
        event.preventDefault();
        this.focusOption('previous');
        return;
      }
    }
    if (event.code === 'Escape') {
      this.resetKeyboardFocus();
      this.expanded = false;
      if (!this.searchable) {
        this.focusDropdown();
      }
      return;
    }
    if (this.anyExpandingKeyPressed(event)) {
      event.preventDefault();
      this.expanded = true;
    }
  }

  @Listen('focus')
  onFocus() {
    if (this.disabled) {
      return;
    }
    if (this.searchable) {
      this.getSearchInputElement().focus();
    }
    this.hasFocus = true;
  }

  @Listen('blur')
  onBlur(event: FocusEvent) {
    if (this.host.contains(event.relatedTarget as Node)) return;
    this.hasFocus = false;
    this.expanded = false;
    this.validateSelect();
  }

  @Listen('groupuiCollapsedChanged')
  onCheckboxGroupCollapseChanged(event: CustomEvent<boolean>) {
    this.updateFocusableItems();

    const index = this.focusableItems.findIndex((item) => item === event.target);
    this.setKeyboardFocus({
      index,
      element: event.target as HTMLGroupuiSelectOptionGroupElement,
      type: 'option-group',
    });
  }

  @Watch('value')
  onValueChange() {
    this.validateSelect();
    if (!this.valueMatchesOption() && !this.valueIsEmpty()) {
      console.warn(Select.CONSOLE_WARN_MESSAGE);
      return;
    }

    this.selectedIconObserver?.disconnect();
    this.observeAllSelectedOptionIcons();

    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  }

  @Watch('invalid')
  onInvalidChange() {
    this.validity = this.getValidity();
    if (this.invalid) {
      this.severity = 'danger';
      this.host.dispatchEvent(new window.Event('invalid'));
      this.groupuiInvalid.emit();
    } else {
      this.severity = 'none';
    }
  }

  @Watch('expanded')
  onExpandedChanged() {
    if (this.expanded) {
      document.addEventListener('mousedown', this.handleOutsideClick, false);
      if (this.searchable) {
        const searchInput = this.getSearchInputElement();
        searchInput.focus();
      }
    } else {
      document.removeEventListener('mousedown', this.handleOutsideClick, false);
      this.validateSelect();
    }
  }

  @Watch('searchValue')
  onSearchValueChange(newSearchValue: string) {
    this.inputTyping.next(newSearchValue);
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.validateSelect({ force: true });
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.subscribeToInputChanges();
    this.validity = this.getValidity();

    if (this.getOptions().length > 0 && !this.valueMatchesOption() && !this.valueIsEmpty()) {
      console.warn(Select.CONSOLE_WARN_MESSAGE);
    }

    this.rerenderWhenIconsAreLoaded();
  }

  componentDidLoad() {
    this.autofocus && this.focusDropdown();
    this.addFormsHandling();

    this.removePreviousHighlights();
    this.groupuiDidLoad.emit();
  }

  componentDidRender() {
    if (this.anyOptionSelected()) {
      this.highlightSelectedOption();
    }
  }

  disconnectedCallback() {
    document.removeEventListener('mousedown', this.handleOutsideClick, false);
    this.selectedIconObserver?.disconnect();
    this.destroy.next();
    this.destroy.complete();
  }

  private subscribeToInputChanges() {
    const debouncedInputTyping = this.inputTyping.pipe(debounceTime(100));
    debouncedInputTyping.pipe(takeUntil(this.destroy)).subscribe((searchTerm) => {
      if (this.searchable && this.builtInSearch) {
        this.filterOptions(searchTerm);
        this.isEveryOptionFilteredOut = !this.isAnyOptionVisible();
      }
    });
  }

  private iconSize() {
    return this.size === 's' ? 16 : 24;
  }

  private isAnyOptionAvailable(): boolean {
    return this.getOptions().length > 0;
  }

  private isAnyOptionVisible(): boolean {
    return Array.from(this.getOptions()).some((option) => {
      return !option.invisible;
    });
  }

  private isPopoverVisible(): boolean {
    return this.expanded && !this.isEveryOptionFilteredOut && this.isAnyOptionAvailable();
  }

  private getGroups() {
    return this.host.querySelectorAll('groupui-select-option-group');
  }

  private filterOptions(searchTerm: string): void {
    this.getOptions().forEach((option) => {
      if (this.caseInsensitiveSearch) {
        option.invisible = !option.textContent.toLowerCase().includes(searchTerm.toLowerCase());
      } else {
        option.invisible = !option.textContent.includes(searchTerm);
      }
    });
    this.getGroups().forEach((group) => {
      const groupOptions = group.querySelectorAll('groupui-select-option');
      group.invisible = Array.from(groupOptions).every((option) => option.invisible);
    });
    this.updateFocusableItems();
  }

  private getOptions() {
    return this.host.querySelectorAll('groupui-select-option');
  }

  private emitSearchStartedEvent() {
    const selectedOption = this.getSelectedOption();
    const selectedOptionEventPayload: SelectedOption | undefined = selectedOption
      ? { value: selectedOption.value, content: selectedOption.textContent }
      : undefined;
    this.groupuiSearchStarted.emit({ selectedOption: selectedOptionEventPayload, searchString: this.searchValue });
  }

  private isSearchInputFocused() {
    return this.searchable && this.getSearchInputElement() === this.host.shadowRoot.activeElement;
  }

  private clearSearchField() {
    const searchInput = this.getSearchInputElement();
    if (!searchInput) return;
    searchInput.value = '';
    this.searchValue = '';
    this.searchOngoing = false;
    this.groupuiSearchCleared.emit();
  }

  private handleOptionSlotChanged = async (event: Event) => {
    const slot = event.target as HTMLSlotElement;
    this.assembleItemsList(slot.assignedElements());
    this.setOptionCallback();
  };

  private assembleItemsList(assignedElements: Element[]) {
    const allBaseOptions: SelectItem[] = [];
    const allOptions: SelectItem[] = [];

    assignedElements.forEach((element) => {
      const processElement = (element) => {
        if (element.tagName === 'GROUPUI-SELECT-OPTION') {
          allBaseOptions.push({ type: 'option', element });
          allOptions.push({ type: 'option', element });
        } else if (element.tagName === 'GROUPUI-SELECT-OPTION-GROUP') {
          allBaseOptions.push({ type: 'option-group', element });
          allOptions.push({ type: 'option-group', element });
          element.childNodes.forEach((child) => {
            if (child.tagName === 'GROUPUI-SELECT-OPTION') {
              allOptions.push({ type: 'option', element: child });
            }
          });
        }
      };
      processElement(element);
    });
    this.allBaseOptions = allBaseOptions;
    this.allOptions = allOptions;

    this.updateFocusableItems();
  }

  private updateFocusableItems() {
    const focusableItems: (HTMLGroupuiSelectOptionElement | HTMLGroupuiSelectOptionGroupElement)[] = [];
    this.allBaseOptions.forEach((item) => {
      if (item.type === 'option' && (item.element.disabled || item.element.invisible)) return;
      if (item.type === 'option') {
        focusableItems.push(item.element);
      } else if (item.type === 'option-group') {
        this.addOptionGroup(item, focusableItems);
        this.addOptionGroupChildren(item, focusableItems);
      }
    });
    this.focusableItems = focusableItems;
  }

  private addOptionGroupChildren(
    optionGroup: {
      type: 'option-group';
      element: HTMLGroupuiSelectOptionGroupElement;
    },
    focusableItems: (HTMLGroupuiSelectOptionElement | HTMLGroupuiSelectOptionGroupElement)[]
  ) {
    if (!optionGroup.element.collapsed) {
      const visibleChildren = Array.from(optionGroup.element.querySelectorAll('groupui-select-option')).filter(
        (child) => !child.invisible
      );
      focusableItems.push(...visibleChildren);
    }
  }

  private addOptionGroup(
    optionGroup: {
      type: 'option-group';
      element: HTMLGroupuiSelectOptionGroupElement;
    },
    focusableItems: (HTMLGroupuiSelectOptionElement | HTMLGroupuiSelectOptionGroupElement)[]
  ) {
    if (!optionGroup.element.invisible && optionGroup.element.expandable) {
      focusableItems.push(optionGroup.element);
    }
  }

  private getSearchInputElement(): HTMLInputElement | null {
    return this.host.shadowRoot.querySelector('input[type="text"]');
  }

  private getVisibleOptionEntries(): {
    index: number;
    option: FocusOption;
  }[] {
    return this.focusableItems.map((option, index) => ({ index, option }));
  }

  private rerenderWhenIconsAreLoaded() {
    this.selectedIconObserver = new MutationObserver(() => {
      forceUpdate(this);
    });

    this.observeAllSelectedOptionIcons();
  }

  private observeAllSelectedOptionIcons() {
    const iconsInSelectedOption = this.getSelectedOption()?.querySelectorAll('groupui-icon');

    iconsInSelectedOption && this.observeAllIcons(iconsInSelectedOption);
  }

  private observeAllIcons(icons: NodeListOf<HTMLGroupuiIconElement>) {
    icons.forEach((icon) => {
      this.selectedIconObserver?.observe(icon.shadowRoot, {
        subtree: true,
        childList: true,
      });
    });
  }

  private handleClearIconClick = (e: Event) => {
    if (this.searchOngoing) {
      this.clearSearchField();
    } else {
      this.value = undefined;
      e.stopPropagation();
      this.groupuiClearClicked.emit();
    }
    if (this.searchable) {
      this.getSearchInputElement().focus();
    } else {
      this.focusDropdown();
    }
  };

  private getValidity() {
    return {
      valid: !this.required || !this.valueIsEmpty(),
      valueMissing: this.required && this.valueIsEmpty(),
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
    };
  }

  private anyExpandingKeyPressed(event: KeyboardEvent) {
    return event.code === 'Enter' || event.code === 'ArrowDown' || event.code === 'ArrowUp' || event.code === 'Space';
  }

  private anySelectingKeyPressed(event: KeyboardEvent) {
    return event.code === 'Enter' || event.code === 'Space';
  }

  private focusOption(direction: 'next' | 'previous') {
    const optionEntries = this.getVisibleOptionEntries();
    if (optionEntries.length === 0) return;
    const keyboardFocus: FocusedOptionInSelect = this.keyboardFocus;

    if (!keyboardFocus) {
      const initialIndex = direction === 'next' ? 0 : optionEntries.length - 1;
      this.setFocusToItem(optionEntries[initialIndex]);
      return;
    }

    const currentOptionIndex = keyboardFocus.index;
    const newEntryIndex =
      direction === 'next'
        ? (currentOptionIndex + 1) % optionEntries.length
        : (currentOptionIndex - 1 + optionEntries.length) % optionEntries.length;

    this.setFocusToItem(optionEntries[newEntryIndex]);
  }

  private setFocusToItem(item: { index: number; option: Element }) {
    if (item.option.tagName === 'GROUPUI-SELECT-OPTION') {
      this.setKeyboardFocus({
        type: 'option',
        index: item.index,
        element: item.option as HTMLGroupuiSelectOptionElement,
      });
    } else {
      this.setKeyboardFocus({
        type: 'option-group',
        index: item.index,
        element: item.option as HTMLGroupuiSelectOptionGroupElement,
      });
    }
  }

  private setKeyboardFocus(keyboardFocus: FocusedOptionInSelect) {
    if (this.keyboardFocus) {
      this.keyboardFocus.element.classList.remove(this.KEYBOARD_FOCUS);
    }

    this.keyboardFocus = keyboardFocus;

    this.keyboardFocus.element.classList.add(this.KEYBOARD_FOCUS);
  }

  private resetKeyboardFocus() {
    if (this.keyboardFocus) {
      this.keyboardFocus.element.classList.remove(this.KEYBOARD_FOCUS);
      this.keyboardFocus = undefined;
    }
  }

  private selectOption(): void {
    if (this.keyboardFocus?.type === 'option-group') {
      this.keyboardFocus.element.collapsed = !this.keyboardFocus.element.collapsed;
    } else if (this.keyboardFocus?.type === 'option') {
      this.onOptionSelected(this.keyboardFocus.element.value)();
    }
  }

  private valueIsEmpty() {
    return this.value === undefined || this.value === null || this.isEmptyString();
  }

  private isEmptyString() {
    return this.value.trim && this.value.trim() === '';
  }

  private getSelectedOption(): HTMLGroupuiSelectOptionElement | undefined {
    return Array.from(this.host.querySelectorAll('groupui-select-option')).find(
      (element) => element.value === this.value
    );
  }

  private getSelectedOptionGroup(): HTMLGroupuiSelectOptionGroupElement | undefined {
    const matchingOptionGroup: SelectItem = this.allBaseOptions
      .filter((option) => option.type === 'option-group')
      .find((optionGroup) => {
        const allOptionsOfOptionGroup: HTMLGroupuiSelectOptionElement[] = Array.from(
          optionGroup.element.querySelectorAll('groupui-select-option')
        );

        return allOptionsOfOptionGroup.some((option) => option.value === this.value);
      });

    return matchingOptionGroup?.element as HTMLGroupuiSelectOptionGroupElement;
  }

  private validateSelect({ force = false }: { force?: boolean } = {}) {
    if (!force && this.noValidation) return;
    this.invalid = !this.getValidity().valid;
  }

  private isClearIconVisible() {
    return this.searchOngoing || (this.showClearIcon && this.anyOptionSelected());
  }

  private addFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event: Event) => {
      this.validateSelect();
      if (this.invalid) {
        event.preventDefault();
      }
    });
  }

  private highlightSelectedOption() {
    this.getSelectedOption()?.classList.add('selected');
    this.getSelectedOptionGroup()?.classList.add('selected');
  }

  private handleOutsideClick = (event: UIEvent) => {
    if (!event.composedPath().includes(this.host)) {
      this.expanded = false;
    }
  };

  private focusDropdown() {
    this.host.focus &&
      (this.host.shadowRoot.querySelector('#selected-option') as HTMLGroupuiSelectOptionElement).focus();
  }

  private setOptionCallback() {
    Array.from(this.host.querySelectorAll('groupui-select-option')).forEach((option) => {
      option.addEventListener('groupuiOptionSelected', this.onOptionSelected(option.value));
    });
  }

  private onOptionSelected(value) {
    return () => {
      this.removePreviousHighlights();

      this.value = value;

      this.resetKeyboardFocus();
      this.expanded = false;
      this.focusDropdown();
      this.clearSearchField();
    };
  }

  private removePreviousHighlights() {
    this.allOptions.forEach((option) => {
      option.element.classList.remove('selected');
    });
  }

  private toggleExpanded = () => {
    this.expanded = !this.expanded;
  };

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private placeholderVisible(): boolean {
    return this.placeholder && !this.anyOptionSelected();
  }

  private anyOptionSelected(): boolean {
    return !this.valueIsEmpty() && this.valueMatchesOption();
  }

  private getInnerHTMLOfSelectedOption(): string {
    const selectedOption = this.getSelectedOption();
    if (!selectedOption) return '';

    const clone = selectedOption.cloneNode(true) as HTMLElement;
    const description = clone.querySelector('[slot="description"]');
    if (description) {
      description.remove();
    }

    return clone.innerHTML;
  }

  private valueMatchesOption(): boolean {
    return Array.from(this.host.querySelectorAll('groupui-select-option')).some(
      (element) => element.value === this.value
    );
  }

  private isDisabledOption(): boolean {
    const selectedOption = this.getSelectedOption();
    return selectedOption.disabled;
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private showDescription() {
    if (!this.descriptionOnlyOnFocus) {
      return true;
    } else {
      return this.hasFocus;
    }
  }

  private setClearFocus = () => {
    if (this.tabbed) {
      this.clearFocus = true;
    }
    this.tabbed = false;
  };

  private resetClearFocus = () => {
    this.clearFocus = false;
  };

  private customAriaLabel = () => {
    if (this.a11yLabelClearButton) return this.a11yLabelClearButton;
    return CLEAR_BUTTON_LABEL;
  };

  private onSearchInput = () => {
    const inputValue = this.getSearchInputElement().value;
    this.searchValue = inputValue;
    this.searchOngoing = inputValue !== '';
    this.expanded = true;
    this.groupuiInput.emit();
  };

  private onSearchFocus = () => {
    this.groupuiInputFocused.emit();
  };

  render() {
    return (
      <Host>
        {this.isLabelSlotProvided() && (
          <label id="label" onClick={this.toggleExpanded} aria-hidden="true">
            <slot name="label" />
          </label>
        )}

        <div id="input-wrapper">
          <groupui-popover visible={this.isPopoverVisible()} full-width={true}>
            <div
              slot="parent"
              id="select"
              onClick={this.toggleExpanded}
              class={{ 'clear-focus': this.clearFocus ? true : undefined }}
            >
              <span
                id="selected-option"
                tabIndex={this.disabled || this.expanded || this.searchable ? -1 : 0}
                role="combobox"
                aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
                aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
                aria-expanded={this.expanded ? 'true' : 'false'}
                aria-controls="content"
                class={{
                  expanded: this.expanded ? true : undefined,
                  focused: this.hasFocus ? true : undefined,
                }}
                {...this.ariaAttributes}
              >
                {this.placeholderVisible() && <div id="placeholder">{this.placeholder}</div>}
                {this.anyOptionSelected() && (
                  <span
                    class={this.isDisabledOption() ? 'disabled' : ''}
                    innerHTML={this.getInnerHTMLOfSelectedOption()}
                  />
                )}
              </span>
              {this.searchable && (
                <input
                  type="text"
                  id="search-input"
                  onInput={this.onSearchInput}
                  onFocus={this.onSearchFocus}
                  value={this.searchValue}
                />
              )}
              {this.useStatusIcon() && (
                <groupui-icon
                  name={this.getStatusIcon()}
                  width={this.iconSize()}
                  height={this.iconSize()}
                  class="status-icon"
                  aria-hidden="true"
                />
              )}
              {this.isClearIconVisible() && (
                <groupui-embedded-button
                  id="clear"
                  icon={`close-${this.iconSize()}`}
                  size={this.size === 'm' ? 'xs' : 'xxs'}
                  onClick={this.handleClearIconClick}
                  onBlur={this.resetClearFocus}
                  onFocus={this.setClearFocus}
                  aria-label={this.customAriaLabel()}
                  aria-describedby={this.isLabelSlotProvided() && !this.a11yLabelClearButton ? 'label' : undefined}
                  aria-hidden={this.readonly || this.disabled ? 'true' : null}
                  disabled={this.readonly || this.disabled}
                ></groupui-embedded-button>
              )}
              <groupui-icon
                id="icon"
                name={this.expanded ? `chevron-up-${this.iconSize()}` : `chevron-down-${this.iconSize()}`}
                aria-hidden="true"
              />
            </div>
            <div slot="content" id="content" style={{ maxHeight: this.maxHeight }}>
              <slot onSlotchange={this.handleOptionSlotChanged} />
            </div>
          </groupui-popover>
        </div>
        {this.isDescriptionSlotProvided() && this.showDescription() && (
          <div id="description" onClick={this.toggleExpanded} aria-hidden="true">
            <slot name="description" />
          </div>
        )}
      </Host>
    );
  }
}
